struct FileCloser { void operator()(std::FILE* f) const noexcept { if (f) std::fclose(f); } };
using FilePtr = std::unique_ptr<std::FILE, FileCloser>;
FilePtr open_log(const char* path) { return FilePtr(std::fopen(path, "a")); }
void run() {
    auto log = open_log("/tmp/app.log");
    if (!log) throw std::runtime_error("open failed");
    // ~FilePtr calls fclose exactly once; log.reset() releases earlier
}
